add_action( 'wp_footer', 'perfectpixel_fade_page_transitions' );

function perfectpixel_fade_page_transitions() {
	$ms = max( 50, min( 2000, (int) '{{page_fade_ms}}' ) );
	?>
	<style>
	body.perfectpixel-fade-out{opacity:0;transition:opacity <?php echo (int) $ms; ?>ms ease}
	@media (prefers-reduced-motion: reduce){body.perfectpixel-fade-out{opacity:1;transition:none}}
	</style>
	<script>
	( function ( ms ) {
		if ( window.matchMedia( '(prefers-reduced-motion: reduce)' ).matches ) {
			return;
		}
		document.addEventListener( 'click', function ( e ) {
			if ( e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey ) {
				return;
			}
			var link = e.target.closest ? e.target.closest( 'a[href]' ) : null;
			if ( ! link || link.target && link.target !== '_self' || link.hasAttribute( 'download' ) ) {
				return;
			}
			var url = new URL( link.href, location.href );
			if ( url.origin !== location.origin || /^(mailto|tel|javascript):/i.test( link.getAttribute( 'href' ) ) ) {
				return;
			}
			if ( url.pathname === location.pathname && url.search === location.search && url.hash ) {
				return;
			}
			if ( url.search.indexOf( 'add-to-cart' ) !== -1 || url.pathname.indexOf( '/wp-admin' ) === 0 || link.classList.contains( 'ajax_add_to_cart' ) ) {
				return;
			}
			e.preventDefault();
			document.body.classList.add( 'perfectpixel-fade-out' );
			setTimeout( function () {
				location.href = url.href;
			}, ms );
		} );
		// Pages restored from the back/forward cache must be visible again.
		window.addEventListener( 'pageshow', function () {
			document.body.classList.remove( 'perfectpixel-fade-out' );
		} );
	} )( <?php echo (int) $ms; ?> );
	</script>
	<?php
}
